    feeds = []
    for feed in config['feeds']:
        result = process_feed(feed['name'], feed['url'])
        feeds.append(result)

    print(json.dumps({'feeds': feeds}))

if __name__ == "__main__":
    main()

import sys
import json
import requests
import xml.etree.ElementTree as ET
from urllib.parse import urlparse

def parse_rss(xml_string):
    try:
        root = ET.fromstring(xml_string)
        channel = root.find('channel')
        if not channel:
            return None
        items = channel.findall('item')
        if not items:
            return None
        first_item = items[0]
        title = first_item.find('title')
        link = first_item.find('link')
        if not title or not link:
            return None
        return {
            'title': title.text,
            'link': link.text
        }
    except ET.ParseError:
        return None

def fetch_feed(url):
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        return response.text
    except requests.RequestException:
        return None

def process_feed(name, url):
    xml_data = fetch_feed(url)
    if not xml_data:
        return {"name": name, "error": "failed"}

    parsed = parse_rss(xml_data)
    if not parsed:
        return {"name": name, "error": "failed"}

    return {
        "name": name,
        "title": parsed['title'],
        "link": parsed['link']
    }

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except (IOError, json.JSONDecodeError):
        sys.exit(1)

    feeds = []
    for feed in config.get('feeds', []):
        if not isinstance(feed, dict) or 'name' not in feed or 'url' not in feed:
            continue
        result = process_feed(feed['name'], feed['url'])
        feeds.append(result)

    print(json.dumps({"feeds": feeds}))

if __name__ == "__main__":
    main()

import json
import requests
import sys
from bs4 import BeautifulSoup

def parse_rss_item(item):
    title = item.find('title')
    link = item.find('link')
    return title.text if title else None, link.text if link else None

def process_feed(feed_name, feed_url):
    try:
        response = requests.get(feed_url)
        response.raise_for_status()
        soup = BeautifulSoup(response.text, 'xml')
        first_item = soup.find('item')
        if not first_item:
            return {"name": feed_name, "error": "failed"}

        title, link = parse_rss_item(first_item)
        if title and link:
            return {"name": feed_name, "title": title, "link": link}
        else:
            return {"name": feed_name, "error": "failed"}
    except Exception:
        return {"name": feed_name, "error": "failed"}

def main():
    if len(sys.argv) != 2:
        print(json.dumps({"feeds": []}), end='')
        return

    config_file = sys.argv[1]
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
    except Exception:
        print(json.dumps({"feeds": [{"name": "failed", "error": "failed"}]}), end='')
        return

    if "feeds" not in config or not isinstance(config["feeds"], list):
        print(json.dumps({"feeds": [{"name": "failed", "error": "failed"}]}), end='')
        return

    results = []
    for feed in config["feeds"]:
        if not isinstance(feed, dict) or "name" not in feed or "url" not in feed:
            results.append({"name": feed.get("name", "failed"), "error": "failed"})
            continue
        results.append(process_feed(feed["name"], feed["url"]))

    print(json.dumps({"feeds": results}), end='')

if __name__ == "__main__":
    main()
